import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailException;
import org.junit.jupiter.api.Test;

/**
 * {@link SailDataset#unwrap(Class)} resolves a store-native dataset through the wrappers sail-base composes around it:
 * the explicit+inferred union, delegating wrappers and the uncommitted-changeset overlay.
 */
public class SailDatasetUnwrapTest {

	/** Marker capability a store-native dataset would expose. */
	interface NativeView {
	}

	/** Minimal dataset; {@code native} ones additionally expose the {@link NativeView} capability. */
	static class StubDataset implements SailDataset {

		@Override
		public void close() throws SailException {
		}

		@Override
		public CloseableIteration<? extends Namespace> getNamespaces() throws SailException {
			return new EmptyIteration<>();
		}

		@Override
		public String getNamespace(String prefix) throws SailException {
			return null;
		}

		@Override
		public CloseableIteration<? extends Resource> getContextIDs() throws SailException {
			return new EmptyIteration<>();
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws SailException {
			return new EmptyIteration<>();
		}
	}

	static final class NativeStubDataset extends StubDataset implements NativeView {
	}

	@Test
	public void defaultUnwrapReturnsSelfOnlyForMatchingType() {
		NativeStubDataset dataset = new NativeStubDataset();
		assertSame(dataset, dataset.unwrap(NativeView.class).orElseThrow());
		assertSame(dataset, dataset.unwrap(SailDataset.class).orElseThrow());
		assertTrue(new StubDataset().unwrap(NativeView.class).isEmpty());
	}

	@Test
	public void unionResolvesTheFirstMemberThatMatches() {
		NativeStubDataset inferred = new NativeStubDataset();
		NativeStubDataset explicit = new NativeStubDataset();
		SailDataset union = UnionSailDataset.getInstance(inferred, explicit);
		assertSame(inferred, union.unwrap(NativeView.class).orElseThrow());
		assertSame(explicit, UnionSailDataset.getInstance(new StubDataset(), explicit)
				.unwrap(NativeView.class)
				.orElseThrow());
		assertSame(union, union.unwrap(SailDataset.class).orElseThrow(), "the union itself matches first");
		assertTrue(UnionSailDataset.getInstance(new StubDataset(), new StubDataset())
				.unwrap(NativeView.class)
				.isEmpty());
	}

	@Test
	public void delegatingAndOverlayDatasetsForwardToTheirBase() {
		NativeStubDataset base = new NativeStubDataset();
		SailDataset delegating = new DelegatingSailDataset(base) {
		};
		assertSame(base, delegating.unwrap(NativeView.class).orElseThrow());

		SailDataset overlay = new SailDatasetImpl(base, new Changeset() {
			@Override
			public void flush() throws SailException {
			}

			@Override
			public Model createEmptyModel() {
				return new LinkedHashModel();
			}
		});
		assertSame(base, overlay.unwrap(NativeView.class).orElseThrow(),
				"the overlay resolves to its committed base dataset");
		assertSame(overlay, overlay.unwrap(SailDataset.class).orElseThrow());
		assertTrue(overlay.unwrap(String.class).isEmpty());
	}

	@Test
	public void tripleTermSourceExposesTheResolution() {
		NativeStubDataset base = new NativeStubDataset();
		SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(SimpleValueFactory.getInstance(),
				UnionSailDataset.getInstance(new StubDataset(), base));
		assertSame(base, source.unwrapDataset(NativeView.class).orElseThrow());
		assertTrue(source.unwrapDataset(String.class).isEmpty());
	}
}
